// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 a, uint256 b) public {
        uint256 A = bound(a, 0, type(uint256).max / 2);
        uint256 B = bound(b, 0, type(uint256).max / 2);

        bool ok1;
        try c.SetMinSum(A) {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        if (!ok1) return;

        uint256 after1 = c.MinSum();

        bool ok2;
        try c.SetMinSum(B) {
            ok2 = true;
        } catch {
            ok2 = false;
        }
        if (!ok2) return;

        uint256 after2 = c.MinSum();

        assertTrue(after2 == B);
    }
}
